import os

for base in [".", "workspace"]:
    print(f"--- {base} ---")
    try:
        for name in sorted(os.listdir(base)):
            full = os.path.join(base, name)
            kind = "dir" if os.path.isdir(full) else "file"
            print(f"{name} ({kind})")
    except FileNotFoundError:
        print("(missing)")

#!/usr/bin/env python3
"""pptx skill helper: append a final slide reading 'Thank you for your attention'
to Q4_financial_report.pptx using python-pptx."""
import os
import sys

try:
    from pptx import Presentation
    from pptx.enum.text import PP_ALIGN
    from pptx.util import Emu, Pt
except ImportError:
    print("ERROR: python-pptx is not installed", file=sys.stderr)
    sys.exit(1)

TARGET = "Q4_financial_report.pptx"
MESSAGE = "Thank you for your attention"


def locate():
    if len(sys.argv) > 1 and os.path.isfile(sys.argv[1]):
        return sys.argv[1]
    for base in (os.getcwd(), os.path.dirname(os.path.abspath(__file__))):
        p = os.path.join(base, TARGET)
        if os.path.isfile(p):
            return p
    raise SystemExit("ERROR: %s not found (cwd=%s)" % (TARGET, os.getcwd()))


def style_centered(tf):
    for para in tf.paragraphs:
        para.alignment = PP_ALIGN.CENTER
        for run in para.runs:
            run.font.size = Pt(40)


def main():
    path = locate()
    prs = Presentation(path)

    # Prefer a layout that has a real title placeholder (idx 0).
    used = None
    for layout in prs.slide_layouts:
        if any(ph.placeholder_format.idx == 0 for ph in layout.placeholders):
            slide = prs.slides.add_slide(layout)
            slide.shapes.title.text = MESSAGE
            style_centered(slide.shapes.title.text_frame)
            used = "title placeholder on layout"
            break
    if used is None:
        slide = prs.slides.add_slide(prs.slide_layouts[0])
        tb = slide.shapes.add_textbox(
            Emu(int(prs.slide_width * 0.10)), Emu(int(prs.slide_height * 0.42)),
            Emu(int(prs.slide_width * 0.80)), Emu(int(prs.slide_height * 0.16)))
        tb.text_frame.text = MESSAGE
        style_centered(tb.text_frame)
        used = "centered text box"

    prs.save(path)
    print("OK: appended final slide (%s) with %r to %s" % (used, MESSAGE, path))


if __name__ == "__main__":
    try:
        main()
    except SystemExit:
        raise
    except Exception as exc:
        print("ERROR: %s: %s" % (type(exc).__name__, exc), file=sys.stderr)
        sys.exit(1)
